/**
 * @param {string} s
 * @return {string}
 */
var smallestSubsequence = function(s) {
    const set = new Set(s);
    const freq = Array(26).fill(0);
    let res = 'z'.repeat(set.size);

    const dfs = (i, j, cur) => {
        if (cur.length === set.size) {
            if (cur < res) {
                res = cur;
            }
            return;
        }
        if (i > j) {
            return;
        }

        const pos = s.charCodeAt(i) - 97;

        if (freq[pos] === 0) {
            dfs(i + 1, j, cur);
            return;
        }

        const count = freq[pos];

        freq[pos] = 0;
        dfs(i + 1, j, cur + s[i]);

        if (count > 1) {
            freq[pos] = count - 1;
            dfs(i + 1, j, cur);
        }

        freq[pos] = count;
    };

    for (let right = 0; right < s.length; right++) {
        const pos = s.charCodeAt(right) - 97;
        freq[pos]++;
    }

    dfs(0, s.length - 1, '');

    return res;
};

/**
 * @param {string} s
 * @return {string}
 */
var smallestSubsequence = function(s) {
    const freq = Array(26).fill(0);

    for (let i = 0; i < s.length; i++) {
        const pos = s.charCodeAt(i) - 97;
        freq[pos]++;
    }

    const seen = Array(26).fill(false);
    const stack = [];

    for (let i = 0; i < s.length; i++) {
        const pos = s.charCodeAt(i) - 97;

        if (!seen[pos]) {
            while (stack[stack.length - 1] > s[i] && freq[stack[stack.length - 1].charCodeAt(0) - 97] > 0) {
                seen[stack[stack.length - 1].charCodeAt(0) - 97] = false;
                stack.pop();
            }
            seen[pos] = true;
            stack.push(s[i]);
        }

        freq[pos]--;
    }

    return stack.join('');
};
